from rich.cells import _cell_len, split_graphemes

def test_zwj_end():
    text = "A\u200d"
    print(f"Text: {text!r}, len: {len(text)}")
    print(f"_cell_len: {_cell_len(text, 'auto')}")
    spans, width = split_graphemes(text, 'auto')
    print(f"split_graphemes spans: {spans}, width: {width}")
    assert spans[-1][1] <= len(text), f"Span end {spans[-1][1]} exceeds text length {len(text)}"

def test_zwj_only():
    text = "\u200d"
    print(f"Text: {text!r}, len: {len(text)}")
    print(f"_cell_len: {_cell_len(text, 'auto')}")
    spans, width = split_graphemes(text, 'auto')
    print(f"split_graphemes spans: {spans}, width: {width}")

def test_zwj_multiple():
    text = "A\u200dB\u200dC"
    print(f"Text: {text!r}, len: {len(text)}")
    print(f"_cell_len: {_cell_len(text, 'auto')}")
    spans, width = split_graphemes(text, 'auto')
    print(f"split_graphemes spans: {spans}, width: {width}")

if __name__ == '__main__':
    try:
        test_zwj_end()
    except Exception as e:
        print(f"test_zwj_end failed: {e}")
    try:
        test_zwj_only()
    except Exception as e:
        print(f"test_zwj_only failed: {e}")
    try:
        test_zwj_multiple()
    except Exception as e:
        print(f"test_zwj_multiple failed: {e}")
